import re

def _safe_int(val):
    if isinstance(val, str) and val.strip() in ('-', 'never', ''):
        return None
    try:
        return int(float(val))
    except (ValueError, TypeError):
        return None

def entities(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    result = []
    seen = set()
    for node in scope_nodes_list:
        if node['kind'] == 'table' and 'Machines' in node['title']:
            for _, cells in table_rows(node):
                m = cells['machine']
                if m not in seen:
                    seen.add(m)
                    desc = f"Machine {m}, CPU={cells['CPU']}, memory={cells['memory']}"
                    fa = cells['fails at']
                    ra = cells['returns at']
                    if _safe_int(fa) is not None:
                        desc += f", fails_at={fa}"
                    if _safe_int(ra) is not None:
                        desc += f", returns_at={ra}"
                    result.append({"id": m, "description": desc})
        if node['kind'] == 'table' and 'Task log' in node['title']:
            for _, cells in table_rows(node):
                t = cells['task']
                if t not in seen:
                    seen.add(t)
                    result.append({
                        "id": t,
                        "description": (f"Task {t}, job={cells['job']}, priority={cells['priority']}, "
                                       f"CPU={cells['CPU']}, memory={cells['memory']}, run_time={cells['run time']}s")
                    })
    return result

def recorded_end(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    for node in scope_nodes_list:
        if node['kind'] == 'text' and 'Cell window' in node['title']:
            m = re.search(r'Times 0 to (\d+)', node['text'])
            if m:
                return float(m.group(1))
    return 1200.0

def inputs(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    result = []
    for node in scope_nodes_list:
        if node['kind'] == 'table' and 'Machines' in node['title']:
            for ri, cells in table_rows(node):
                m = cells['machine']
                fa = cells['fails at']
                ra = cells['returns at']
                fa_val = _safe_int(fa)
                ra_val = _safe_int(ra)

                result.append({
                    "id": f"machine_{m}",
                    "time": 0,
                    "kind": "machine_spec",
                    "entities": [m],
                    "fields": {
                        "CPU": int(cells['CPU']),
                        "memory": int(cells['memory']),
                        "fails_at": fa_val,
                        "returns_at": ra_val,
                    },
                    "src": [[node['node_id'], ri, ['machine', 'CPU', 'memory', 'fails at', 'returns at']]]
                })

                if fa_val is not None:
                    result.append({
                        "id": f"machine_fail_{m}",
                        "time": fa_val,
                        "kind": "machine_failure",
                        "entities": [m],
                        "fields": {},
                        "src": [[node['node_id'], ri, ['machine', 'fails at']]]
                    })
                if ra_val is not None:
                    result.append({
                        "id": f"machine_return_{m}",
                        "time": ra_val,
                        "kind": "machine_return",
                        "entities": [m],
                        "fields": {},
                        "src": [[node['node_id'], ri, ['machine', 'returns at']]]
                    })

        if node['kind'] == 'table' and 'Task log' in node['title']:
            for ri, cells in table_rows(node):
                if cells['event'] == 'submit':
                    t = cells['task']
                    result.append({
                        "id": f"submit_{t}",
                        "time": int(cells['time']),
                        "kind": "task_submission",
                        "entities": [t],
                        "fields": {
                            "job": cells['job'],
                            "priority": int(cells['priority']),
                            "CPU": int(cells['CPU']),
                            "memory": int(cells['memory']),
                            "run_time": int(cells['run time']),
                        },
                        "src": [[node['node_id'], ri, ['time', 'task', 'job', 'priority', 'CPU', 'memory', 'run time', 'event', 'machine']]]
                    })
    return result

def outcomes(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    result = []
    for node in scope_nodes_list:
        if node['kind'] == 'table' and 'Task log' in node['title']:
            for ri, cells in table_rows(node):
                ev = cells['event']
                if ev in ('start', 'finish', 'evict', 'fail'):
                    t = cells['task']
                    mc = cells['machine']
                    ents = [t]
                    if mc != '-':
                        ents.append(mc)
                    result.append({
                        "time": int(cells['time']),
                        "kind": ev,
                        "entities": ents,
                        "value": None,
                        "src": [[node['node_id'], ri, ['time', 'task', 'job', 'priority', 'CPU', 'memory', 'run time', 'event', 'machine']]]
                    })

        if node['kind'] == 'table' and 'Queue at window end' in node['title']:
            for ri, cells in table_rows(node):
                t = cells['task']
                mc = cells['machine']
                ents = [t]
                if mc != '-':
                    ents.append(mc)
                rem = cells['remaining']
                result.append({
                    "time": 1200,
                    "kind": "queue_state",
                    "entities": ents,
                    "value": _safe_int(rem),
                    "src": [[node['node_id'], ri, ['task', 'job', 'priority', 'CPU', 'memory', 'machine', 'started', 'remaining']]]
                })

        if node['kind'] == 'list' and 'Events' in node['title']:
            for i, line in enumerate(node['lines']):
                tm = re.match(r'Time (\d+):', line)
                t = int(tm.group(1)) if tm else None
                ents = []
                for x in re.findall(r'(?:M|T)\d+', line):
                    if x not in ents:
                        ents.append(x)
                val = None
                wm = re.search(r'longest wait.*?(\d+)s?', line)
                if wm:
                    val = int(wm.group(1))
                result.append({
                    "time": t,
                    "kind": "event_narrative",
                    "entities": ents,
                    "value": val,
                    "src": [[node['node_id'], i]]
                })
    return result

def params(doc, scope):
    return {"window_length": 1200, "num_machines": 8}


# ---- step 2: forward model ----
import heapq

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    machines = {}
    sub_events = {}
    fail_events = {}
    ret_events = {}

    for inp in inputs:
        k, t = inp['kind'], inp['time']
        if k == 'machine_spec':
            mid = inp['entities'][0]
            machines[mid] = {'cap_cpu': inp['fields']['CPU'], 'cap_mem': inp['fields']['memory'], 'free_cpu': inp['fields']['CPU'], 'free_mem': inp['fields']['memory'], 'up': True}
        elif k == 'task_submission':
            sub_events.setdefault(t, []).append({'id': inp['entities'][0], 'priority': inp['fields']['priority'], 'cpu': inp['fields']['CPU'], 'mem': inp['fields']['memory'], 'run_time': inp['fields']['run_time'], 'submit_time': t, 'start_time': None, 'finish_time': None})
        elif k == 'machine_failure':
            fail_events.setdefault(t, []).append(inp['entities'][0])
        elif k == 'machine_return':
            ret_events.setdefault(t, []).append(inp['entities'][0])

    queue = []
    running = {m: [] for m in machines}
    outcomes = []
    end_time = horizon if horizon is not None else params.get('window_length', 1200)

    pq = []
    for t in list(sub_events.keys()) + list(fail_events.keys()) + list(ret_events.keys()):
        heapq.heappush(pq, t)

    def add_finish(time):
        heapq.heappush(pq, time)

    def task_key(tk):
        return (-tk['priority'], tk['submit_time'], int(tk['id'][1:]))

    def evict_key(tk):
        return (tk['priority'], -tk['start_time'], -int(tk['id'][1:]))

    while pq:
        t = heapq.heappop(pq)
        while pq and pq[0] == t:
            heapq.heappop(pq)

        if t > end_time:
            if not queue and not any(running.values()):
                break
            continue

        # 1. Finishes
        for m_id in list(running.keys()):
            new_t = []
            for tk in running[m_id]:
                if tk['finish_time'] == t:
                    outcomes.append({'time': t, 'kind': 'finish', 'entities': [tk['id'], m_id], 'value': None, 'src': None})
                    machines[m_id]['free_cpu'] += tk['cpu']
                    machines[m_id]['free_mem'] += tk['mem']
                else:
                    new_t.append(tk)
            running[m_id] = new_t

        # 2. Failures
        if t in fail_events:
            for m_id in fail_events[t]:
                if m_id in machines and machines[m_id]['up']:
                    machines[m_id]['up'] = False
                    for tk in running[m_id]:
                        outcomes.append({'time': t, 'kind': 'fail', 'entities': [tk['id'], m_id], 'value': None, 'src': None})
                        queue.append(tk)
                    running[m_id] = []

        # 3. Returns
        if t in ret_events:
            for m_id in ret_events[t]:
                if m_id in machines and not machines[m_id]['up']:
                    machines[m_id]['up'] = True
                    machines[m_id]['free_cpu'] = machines[m_id]['cap_cpu']
                    machines[m_id]['free_mem'] = machines[m_id]['cap_mem']
                    running[m_id] = []

        # 4. Submissions
        if t in sub_events:
            queue.extend(sub_events[t])

        # 5. Scheduling round
        if queue:
            queue.sort(key=task_key)
            reservation = None

            i = 0
            while i < len(queue):
                task = queue[i]
                started = False

                # a. First fit
                for m_id in sorted(machines.keys()):
                    m = machines[m_id]
                    if not m['up'] or m['free_cpu'] < task['cpu'] or m['free_mem'] < task['mem']:
                        continue

                    if reservation and m_id == reservation[0]:
                        avail_c = reservation[4] - reservation[2] - reservation[6]
                        avail_m = reservation[5] - reservation[3] - reservation[7]
                        if not ((t + task['run_time'] <= reservation[1]) or (task['cpu'] <= avail_c and task['mem'] <= avail_m)):
                            continue

                    outcomes.append({'time': t, 'kind': 'start', 'entities': [task['id'], m_id], 'value': None, 'src': None})
                    m['free_cpu'] -= task['cpu']
                    m['free_mem'] -= task['mem']
                    if reservation and m_id == reservation[0]:
                        reservation = (reservation[0], reservation[1], reservation[2], reservation[3], reservation[4], reservation[5], reservation[6] + task['cpu'], reservation[7] + task['mem'])
                    task['finish_time'] = t + task['run_time']
                    task['start_time'] = t
                    running[m_id].append(task)
                    add_finish(task['finish_time'])
                    started = True
                    break

                if not started:
                    # b. Preemption
                    if not reservation and task['priority'] >= 9:
                        for m_id in sorted(machines.keys()):
                            m = machines[m_id]
                            if not m['up']:
                                continue
                            cands = sorted([tk for tk in running[m_id] if tk['priority'] <= 1], key=evict_key)
                            if not cands:
                                continue
                            tmp_c, tmp_m, to_ev = m['free_cpu'], m['free_mem'], []
                            for c in cands:
                                if tmp_c >= task['cpu'] and tmp_m >= task['mem']:
                                    break
                                tmp_c += c['cpu']
                                tmp_m += c['mem']
                                to_ev.append(c)

                            if tmp_c >= task['cpu'] and tmp_m >= task['mem']:
                                for ev in to_ev:
                                    outcomes.append({'time': t, 'kind': 'evict', 'entities': [ev['id'], m_id], 'value': None, 'src': None})
                                    m['free_cpu'] += ev['cpu']
                                    m['free_mem'] += ev['mem']
                                    running[m_id].remove(ev)
                                    queue.append(ev)
                                outcomes.append({'time': t, 'kind': 'start', 'entities': [task['id'], m_id], 'value': None, 'src': None})
                                m['free_cpu'] -= task['cpu']
                                m['free_mem'] -= task['mem']
                                task['finish_time'] = t + task['run_time']
                                task['start_time'] = t
                                running[m_id].append(task)
                                add_finish(task['finish_time'])
                                started = True
                                break

                if not started:
                    # c. Reservation
                    if not reservation:
                        best_t, best_m = None, None
                        for mid in sorted(machines.keys()):
                            mm = machines[mid]
                            if not mm['up'] or mm['cap_cpu'] < task['cpu'] or mm['cap_mem'] < task['mem']:
                                continue
                            fc, fm = mm['free_cpu'], mm['free_mem']
                            if fc >= task['cpu'] and fm >= task['mem']:
                                avail = t
                            else:
                                evts = sorted([(rk['finish_time'], rk['cpu'], rk['mem']) for rk in running[mid]])
                                avail = None
                                for ft, frc, frm in evts:
                                    fc += frc
                                    fm += frm
                                    if fc >= task['cpu'] and fm >= task['mem']:
                                        avail = ft
                                        break
                                if avail is None:
                                    avail = evts[-1][0] if evts else t + 999999
                            if best_t is None or avail < best_t:
                                best_t, best_m = avail, mid
                            elif avail == best_t and (best_m is None or mid < best_m):
                                best_m = mid

                        if best_m is not None:
                            mm = machines[best_m]
                            cap_c = mm['free_cpu'] + sum(rk['cpu'] for rk in running[best_m] if rk['finish_time'] <= best_t)
                            cap_m = mm['free_mem'] + sum(rk['mem'] for rk in running[best_m] if rk['finish_time'] <= best_t)
                            reservation = (best_m, best_t, task['cpu'], task['mem'], cap_c, cap_m, 0, 0)

                if started:
                    queue.pop(i)
                else:
                    i += 1

    lower = start if start is not None else -1
    upper = end_time if end_time is not None else float('inf')
    return [o for o in outcomes if lower < o['time'] <= upper]

