def simulate(doc, scope, inputs, params, start=None, horizon=None):
    import heapq
    machines = {}
    sub_events = {}
    fail_events = {}
    ret_events = {}

    for inp in inputs:
        k = inp['kind']
        t = inp['time']
        if k == 'machine_spec':
            mid = inp['entities'][0]
            machines[mid] = {
                'id': mid,
                'cap_cpu': inp['fields']['CPU'],
                'cap_mem': inp['fields']['memory'],
                'free_cpu': inp['fields']['CPU'],
                'free_mem': inp['fields']['memory'],
                'up': True,
                'fail_time': inp['fields'].get('fails_at'),
                'return_time': inp['fields'].get('returns_at')
            }
        elif k == 'task_submission':
            tid = inp['entities'][0]
            sub_events.setdefault(t, []).append({
                'id': tid,
                'job': inp['fields']['job'],
                'priority': inp['fields']['priority'],
                'cpu': inp['fields']['CPU'],
                'mem': inp['fields']['memory'],
                'run_time': inp['fields']['run_time'],
                'submit_time': t,
                'start_time': None,
                'finish_time': None
            })
        elif k == 'machine_failure':
            mid = inp['entities'][0]
            fail_events.setdefault(t, []).append(mid)
        elif k == 'machine_return':
            mid = inp['entities'][0]
            ret_events.setdefault(t, []).append(mid)

    queue = []
    running = {mid: [] for mid in machines}
    outcomes = []

    end_time = horizon if horizon is not None else params.get('window_length', 1200)

    pq = []
    for t in sub_events: heapq.heappush(pq, t)
    for t in fail_events: heapq.heappush(pq, t)
    for t in ret_events: heapq.heappush(pq, t)

    def add_finish(time):
        heapq.heappush(pq, time)

    def task_sort_key(tk):
        tid_num = int(''.join(filter(str.isdigit, tk['id'])))
        return (-tk['priority'], tk['submit_time'], tid_num)

    def evict_sort_key(tk):
        tid_num = int(''.join(filter(str.isdigit, tk['id'])))
        return (tk['priority'], -tk['start_time'], -tid_num)

    def get_earliest_start(machine, task_cpu, task_mem, current_time):
        m = machines[machine]
        if not m['up'] or m['cap_cpu'] < task_cpu or m['cap_mem'] < task_mem:
            return None
        free_c = m['free_cpu']
        free_m = m['free_mem']
        if free_c >= task_cpu and free_m >= task_mem:
            return current_time

        events = sorted([(tk['finish_time'], tk['cpu'], tk['mem']) for tk in running[machine]])
        for ft, fc, fm in events:
            free_c += fc
            free_m += fm
            if free_c >= task_cpu and free_m >= task_mem:
                return ft
        return None

    while pq:
        t = heapq.heappop(pq)
        while pq and pq[0] == t:
            heapq.heappop(pq)

        if t > end_time:
            if not queue and not any(running.values()):
                break
            continue

        # 1. Finishes
        finishing = []
        for m_id, tasks in running.items():
            new_tasks = []
            for task in tasks:
                if task['finish_time'] == t:
                    finishing.append((task, m_id))
                else:
                    new_tasks.append(task)
            running[m_id] = new_tasks

        for task, m_id in finishing:
            outcomes.append({'time': t, 'kind': 'finish', 'entities': [task['id'], m_id], 'value': None, 'src': None})
            machines[m_id]['free_cpu'] += task['cpu']
            machines[m_id]['free_mem'] += task['mem']

        # 2. Failures
        if t in fail_events:
            for m_id in fail_events[t]:
                if m_id in machines and machines[m_id]['up']:
                    machines[m_id]['up'] = False
                    for task in running[m_id]:
                        outcomes.append({'time': t, 'kind': 'fail', 'entities': [task['id'], m_id], 'value': None, 'src': None})
                        machines[m_id]['free_cpu'] += task['cpu']
                        machines[m_id]['free_mem'] += task['mem']
                        queue.append(task)
                    running[m_id] = []

        # 3. Returns
        if t in ret_events:
            for m_id in ret_events[t]:
                if m_id in machines and not machines[m_id]['up']:
                    machines[m_id]['up'] = True
                    machines[m_id]['free_cpu'] = machines[m_id]['cap_cpu']
                    machines[m_id]['free_mem'] = machines[m_id]['cap_mem']
                    running[m_id] = []

        # 4. Submissions
        if t in sub_events:
            for task in sub_events[t]:
                queue.append(task)

        # 5. Scheduling round
        if queue:
            queue.sort(key=task_sort_key)
            reservation = None
            reserved_gap_cpu = 0
            reserved_gap_mem = 0

            i = 0
            while i < len(queue):
                task = queue[i]
                started = False

                # a. First fit
                for m_id in sorted(machines.keys()):
                    m = machines[m_id]
                    if not m['up']: continue
                    if m['free_cpu'] < task['cpu'] or m['free_mem'] < task['mem']: continue

                    if reservation and m_id == reservation[0]:
                        cond1 = (t + task['run_time']) <= reservation[1]
                        cond2 = (task['cpu'] <= reserved_gap_cpu and task['mem'] <= reserved_gap_mem)
                        if not (cond1 or cond2):
                            continue

                    outcomes.append({'time': t, 'kind': 'start', 'entities': [task['id'], m_id], 'value': None, 'src': None})
                    m['free_cpu'] -= task['cpu']
                    m['free_mem'] -= task['mem']
                    if reservation and m_id == reservation[0]:
                        reserved_gap_cpu -= task['cpu']
                        reserved_gap_mem -= task['mem']
                    task['finish_time'] = t + task['run_time']
                    task['start_time'] = t
                    running[m_id].append(task)
                    add_finish(task['finish_time'])
                    started = True
                    break

                if not started:
                    # b. Preemption
                    if not reservation and task['priority'] >= 9:
                        for m_id in sorted(machines.keys()):
                            m = machines[m_id]
                            if not m['up']: continue

                            candidates = [tk for tk in running[m_id] if tk['priority'] <= 1]
                            if not candidates: continue
                            candidates.sort(key=evict_sort_key)

                            temp_cpu = m['free_cpu']
                            temp_mem = m['free_mem']
                            to_evict = []
                            for cand in candidates:
                                if temp_cpu >= task['cpu'] and temp_mem >= task['mem']:
                                    break
                                temp_cpu += cand['cpu']
                                temp_mem += cand['mem']
                                to_evict.append(cand)

                            if temp_cpu >= task['cpu'] and temp_mem >= task['mem']:
                                for ev in to_evict:
                                    outcomes.append({'time': t, 'kind': 'evict', 'entities': [ev['id'], m_id], 'value': None, 'src': None})
                                    m['free_cpu'] += ev['cpu']
                                    m['free_mem'] += ev['mem']
                                    running[m_id].remove(ev)
                                    queue.append(ev)
                                outcomes.append({'time': t, 'kind': 'start', 'entities': [task['id'], m_id], 'value': None, 'src': None})
                                m['free_cpu'] -= task['cpu']
                                m['free_mem'] -= task['mem']
                                task['finish_time'] = t + task['run_time']
                                task['start_time'] = t
                                running[m_id].append(task)
                                add_finish(task['finish_time'])
                                started = True
                                break

                if not started:
                    # c. Reservation
                    if not reservation:
                        best_time = None
                        best_m_id = None
                        for m_id in sorted(machines.keys()):
                            est = get_earliest_start(m_id, task['cpu'], task['mem'], t)
                            if est is not None:
                                if best_time is None or est < best_time:
                                    best_time = est
                                    best_m_id = m_id
                                elif est == best_time and (best_m_id is None or m_id < best_m_id):
                                    best_m_id = m_id

                        if best_m_id is not None:
                            reservation = (best_m_id, best_time)
                            m = machines[best_m_id]
                            gap_c = m['free_cpu']
                            gap_m = m['free_mem']
                            for tk in running[best_m_id]:
                                if tk['finish_time'] <= best_time:
                                    gap_c += tk['cpu']
                                    gap_m += tk['mem']
                            reserved_gap_cpu = gap_c - task['cpu']
                            reserved_gap_mem = gap_m - task['mem']

                if started:
                    queue.pop(i)
                else:
                    i += 1

    res = [o for o in outcomes if o['time'] > (start if start is not None else -1)]
    return res

sim_outs = simulate(doc, 'Cell window 04', inputs(doc, 'Cell window 04'), params(doc, 'Cell window 04'), start=0, horizon=1200)
recorded_outs = outcomes(doc, 'Cell window 04')

