            tid = inp['entities'][0]
            sub_events.setdefault(t, []).append({'id': tid, 'priority': inp['fields']['priority'], 'cpu': inp['fields']['CPU'], 'mem': inp['fields']['memory'], 'run_time': inp['fields']['run_time'], 'submit_time': t, 'start_time': None, 'finish_time': None})
        elif k == 'machine_failure':
            fail_events.setdefault(t, []).append(inp['entities'][0])
        elif k == 'machine_return':
            ret_events.setdefault(t, []).append(inp['entities'][0])

    queue = []
    running = {m: [] for m in machines}
    outcomes = []
    end_time = horizon if horizon else params.get('window_length', 1200)

    pq = []
    for t in list(set(list(sub_events.keys()) + list(fail_events.keys()) + list(ret_events.keys()))):
