import heapq

def simulate_v2(inputs, params, start=None, horizon=None):
    machines = {}
    sub_events = {}
    fail_events = {}
    ret_events = {}
    for inp in inputs:
        k, t = inp['kind'], inp['time']
        if k == 'machine_spec':
            mid = inp['entities'][0]
            machines[mid] = {'cap_cpu': inp['fields']['CPU'], 'cap_mem': inp['fields']['memory'], 'free_cpu': inp['fields']['CPU'], 'free_mem': inp['fields']['memory'], 'up': True}
        elif k == 'task_submission':
            sub_events.setdefault(t, []).append({'id': inp['entities'][0], 'priority': inp['fields']['priority'], 'cpu': inp['fields']['CPU'], 'mem': inp['fields']['memory'], 'run_time': inp['fields']['run_time'], 'submit_time': t, 'start_time': None, 'finish_time': None})
        elif k == 'machine_failure':
            fail_events.setdefault(t, []).append(inp['entities'][0])
        elif k == 'machine_return':
            ret_events.setdefault(t, []).append(inp['entities'][0])

    queue = []
    running = {m: [] for m in machines}
    outcomes = []
    end_time = horizon if horizon else params.get('window_length', 1200)
    pq = list(set(list(sub_events.keys()) + list(fail_events.keys()) + list(ret_events.keys())))
    heapq.heapify(pq)

    def add_finish(time): heapq.heappush(pq, time)
    def task_key(tk): return (-tk['priority'], tk['submit_time'], int(''.join(filter(str.isdigit, tk['id']))))
    def evict_key(tk): return (tk['priority'], -tk['start_time'], -int(''.join(filter(str.isdigit, tk['id']))))

    while pq:
        t = heapq.heappop(pq)
        while pq and pq[0] == t: heapq.heappop(pq)
        if t > end_time and not queue and not any(running.values()): break

        for m_id in list(running.keys()):
            new_t = []
            for tk in running[m_id]:
                if tk['finish_time'] == t:
                    outcomes.append({'time': t, 'kind': 'finish', 'entities': [tk['id'], m_id], 'value': None})
                    machines[m_id]['free_cpu'] += tk['cpu']; machines[m_id]['free_mem'] += tk['mem']
                else: new_t.append(tk)
            running[m_id] = new_t

        if t in fail_events:
            for m_id in fail_events[t]:
                if m_id in machines and machines[m_id]['up']:
                    machines[m_id]['up'] = False
                    for tk in running[m_id]:
                        outcomes.append({'time': t, 'kind': 'fail', 'entities': [tk['id'], m_id], 'value': None}); queue.append(tk)
                    running[m_id] = []

        if t in ret_events:
            for m_id in ret_events[t]:
                if m_id in machines and not machines[m_id]['up']:
                    machines[m_id]['up'] = True; machines[m_id]['free_cpu'] = machines[m_id]['cap_cpu']; machines[m_id]['free_mem'] = machines[m_id]['cap_mem']; running[m_id] = []

        if t in sub_events: queue.extend(sub_events[t])

        if queue:
            queue.sort(key=task_key)
            reservation = None
            i = 0
            while i < len(queue):
                task = queue[i]
                started = False
                for m_id in sorted(machines.keys()):
                    m = machines[m_id]
                    if not m['up'] or m['free_cpu'] < task['cpu'] or m['free_mem'] < task['mem']: continue
                    if reservation and m_id == reservation[0]:
                        if not ((t + task['run_time'] <= reservation[1]) or (task['cpu'] <= (reservation[4] - reservation[2] - reservation[6]) and task['mem'] <= (reservation[5] - reservation[3] - reservation[7]))): continue
                    outcomes.append({'time': t, 'kind': 'start', 'entities': [task['id'], m_id], 'value': None})
                    m['free_cpu'] -= task['cpu']; m['free_mem'] -= task['mem']
                    if reservation and m_id == reservation[0]: reservation = (*reservation[:6], reservation[6]+task['cpu'], reservation[7]+task['mem'])
                    task['finish_time'] = t + task['run_time']; task['start_time'] = t
                    running[m_id].append(task); add_finish(task['finish_time']); started = True; break
                if not started:
                    if not reservation and task['priority'] >= 9:
                        for m_id in sorted(machines.keys()):
                            m = machines[m_id]
                            if not m['up']: continue
                            cands = sorted([tk for tk in running[m_id] if tk['priority'] <= 1], key=evict_key)
                            if not cands: continue
                            tmp_c, tmp_m, to_ev = m['free_cpu'], m['free_mem'], []
                            for c in cands:
                                if tmp_c >= task['cpu'] and tmp_m >= task['mem']: break
                                tmp_c += c['cpu']; tmp_m += c['mem']; to_ev.append(c)
                            if tmp_c >= task['cpu'] and tmp_m >= task['mem']:
                                for ev in to_ev:
                                    outcomes.append({'time': t, 'kind': 'evict', 'entities': [ev['id'], m_id], 'value': None})
                                    m['free_cpu'] += ev['cpu']; m['free_mem'] += ev['mem']; running[m_id].remove(ev); queue.append(ev)
                                outcomes.append({'time': t, 'kind': 'start', 'entities': [task['id'], m_id], 'value': None})
                                m['free_cpu'] -= task['cpu']; m['free_mem'] -= task['mem']
                                task['finish_time'] = t + task['run_time']; task['start_time'] = t
                                running[m_id].append(task); add_finish(task['finish_time']); started = True; break
                if not started:
                    if not reservation:
                        best_t, best_m = None, None
                        for mid in sorted(machines.keys()):
                            mm = machines[mid]
                            if not mm['up'] or mm['cap_cpu'] < task['cpu'] or mm['cap_mem'] < task['mem']: continue
                            fc, fm = mm['free_cpu'], mm['free_mem']
                            if fc >= task['cpu'] and fm >= task['mem']: avail = t
                            else:
                                evts = sorted([(rk['finish_time'], rk['cpu'], rk['mem']) for rk in running[mid]])
                                avail = None
                                for ft, frc, frm in evts:
                                    fc += frc; fm += frm
                                    if fc >= task['cpu'] and fm >= task['mem']: avail = ft; break
                                if avail is None: avail = evts[-1][0] if evts else t + 999999
                            if best_t is None or avail < best_t: best_t, best_m = avail, mid
                            elif avail == best_t and (best_m is None or mid < best_m): best_m = mid
                        if best_m is not None:
                            mm = machines[best_m]
                            cap_c = mm['free_cpu'] + sum(rk['cpu'] for rk in running[best_m] if rk['finish_time'] <= best_t)
                            cap_m = mm['free_mem'] + sum(rk['mem'] for rk in running[best_m] if rk['finish_time'] <= best_t)
                            reservation = (best_m, best_t, task['cpu'], task['mem'], cap_c, cap_m, 0, 0)
                if started: queue.pop(i)
                else: i += 1
    return [o for o in outcomes if o['time'] > (start if start else -1)]

