print(f"Sim <=1200: {len(sim_1200)}, Rec: {len(rec)}")
def norm(o): return (o['time'], o['kind'], o['entities'])
diff = set(norm(s) for s in sim_1200) ^ set(norm(r) for r in rec)
if diff: print("Diff:", sorted(list(diff))[:5])
else: print("Match 04!")

