import re

def _safe_int(val):
    if isinstance(val, str) and val.strip() in ('-', 'never', ''):
        return None
    try:
        return int(float(val))
    except (ValueError, TypeError):
        return None

def entities(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    result = []
    seen = set()
    for node in scope_nodes_list:
        if node['kind'] == 'table' and 'Machines' in node['title']:
            for _, cells in table_rows(node):
                m = cells['machine']
                if m not in seen:
                    seen.add(m)
                    desc = f"Machine {m}, CPU={cells['CPU']}, memory={cells['memory']}"
                    fa = cells['fails at']
                    ra = cells['returns at']
                    if _safe_int(fa) is not None:
                        desc += f", fails_at={fa}"
                    if _safe_int(ra) is not None:
                        desc += f", returns_at={ra}"
                    result.append({"id": m, "description": desc})
        if node['kind'] == 'table' and 'Task log' in node['title']:
            for _, cells in table_rows(node):
                t = cells['task']
                if t not in seen:
                    seen.add(t)
                    result.append({
                        "id": t,
                        "description": (f"Task {t}, job={cells['job']}, priority={cells['priority']}, "
                                       f"CPU={cells['CPU']}, memory={cells['memory']}, run_time={cells['run time']}s")
                    })
    return result

def recorded_end(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    for node in scope_nodes_list:
        if node['kind'] == 'text' and 'Cell window' in node['title']:
            m = re.search(r'Times 0 to (\d+)', node['text'])
            if m:
                return float(m.group(1))
    return 1200.0

def inputs(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    result = []
    for node in scope_nodes_list:
        if node['kind'] == 'table' and 'Machines' in node['title']:
            for ri, cells in table_rows(node):
                m = cells['machine']
                fa = cells['fails at']
                ra = cells['returns at']
                fa_val = _safe_int(fa)
                ra_val = _safe_int(ra)

                result.append({
                    "id": f"machine_{m}",
                    "time": 0,
                    "kind": "machine_spec",
                    "entities": [m],
                    "fields": {
                        "CPU": int(cells['CPU']),
                        "memory": int(cells['memory']),
                        "fails_at": fa_val,
                        "returns_at": ra_val,
                    },
                    "src": [[node['node_id'], ri, ['machine', 'CPU', 'memory', 'fails at', 'returns at']]]
                })

                if fa_val is not None:
                    result.append({
                        "id": f"machine_fail_{m}",
                        "time": fa_val,
                        "kind": "machine_failure",
                        "entities": [m],
                        "fields": {},
                        "src": [[node['node_id'], ri, ['machine', 'fails at']]]
                    })
                if ra_val is not None:
                    result.append({
                        "id": f"machine_return_{m}",
                        "time": ra_val,
                        "kind": "machine_return",
                        "entities": [m],
                        "fields": {},
                        "src": [[node['node_id'], ri, ['machine', 'returns at']]]
                    })

        if node['kind'] == 'table' and 'Task log' in node['title']:
            for ri, cells in table_rows(node):
                if cells['event'] == 'submit':
                    t = cells['task']
                    result.append({
                        "id": f"submit_{t}",
                        "time": int(cells['time']),
                        "kind": "task_submission",
                        "entities": [t],
                        "fields": {
                            "job": cells['job'],
                            "priority": int(cells['priority']),
                            "CPU": int(cells['CPU']),
                            "memory": int(cells['memory']),
                            "run_time": int(cells['run time']),
                        },
                        "src": [[node['node_id'], ri, ['time', 'task', 'job', 'priority', 'CPU', 'memory', 'run time', 'event', 'machine']]]
                    })
    return result

def outcomes(doc, scope):
    scope_nodes_list = scope_nodes(doc, scope)
    result = []
    for node in scope_nodes_list:
        if node['kind'] == 'table' and 'Task log' in node['title']:
            for ri, cells in table_rows(node):
                ev = cells['event']
                if ev in ('start', 'finish', 'evict', 'fail'):
                    t = cells['task']
                    mc = cells['machine']
                    ents = [t]
                    if mc != '-':
                        ents.append(mc)
                    result.append({
                        "time": int(cells['time']),
                        "kind": ev,
                        "entities": ents,
                        "value": None,
                        "src": [[node['node_id'], ri, ['time', 'task', 'job', 'priority', 'CPU', 'memory', 'run time', 'event', 'machine']]]
                    })

        if node['kind'] == 'table' and 'Queue at window end' in node['title']:
            for ri, cells in table_rows(node):
                t = cells['task']
                mc = cells['machine']
                ents = [t]
                if mc != '-':
                    ents.append(mc)
                rem = cells['remaining']
                result.append({
                    "time": 1200,
                    "kind": "queue_state",
                    "entities": ents,
                    "value": _safe_int(rem),
                    "src": [[node['node_id'], ri, ['task', 'job', 'priority', 'CPU', 'memory', 'machine', 'started', 'remaining']]]
                })

        if node['kind'] == 'list' and 'Events' in node['title']:
            for i, line in enumerate(node['lines']):
                tm = re.match(r'Time (\d+):', line)
                t = int(tm.group(1)) if tm else None
                ents = []
                for x in re.findall(r'(?:M|T)\d+', line):
                    if x not in ents:
                        ents.append(x)
                val = None
                wm = re.search(r'longest wait.*?(\d+)s?', line)
                if wm:
                    val = int(wm.group(1))
                result.append({
                    "time": t,
                    "kind": "event_narrative",
                    "entities": ents,
                    "value": val,
                    "src": [[node['node_id'], i]]
                })
    return result

